local config = {
  ui_story_30460401_1_dialog_content = "Sejak Keating Choir tiba, banyak orang bilang ada yang tidak beres dengan cara mereka berbicara.",
  ui_story_30460401_2_dialog_content = "Aku telah bilang pada semua orang bahwa mereka harus memberi tahu anak-anak apa yang mereka pikirkan secara langsung.",
  ui_story_30460401_3_dialog_content = "Namun, semua orang bilang lebih baik tetap diam.",
  ui_story_30460401_4_dialog_content = "Halo, orang dewasa, bagaimana kondisi mentalmu?",
  ui_story_30460401_5_dialog_content = "Kenapa kamu tampak begitu terganggu? Kamu bicara pada diri sendiri?",
  ui_story_30460401_6_dialog_content = "Maaf, aku sedang memikirkan sesuatu.",
  ui_story_30460401_7_dialog_content = "Aku memikirkan mengapa kalian suka mengejek atau mengolok-olok orang lain sepanjang waktu.",
  ui_story_30460401_8_dialog_content = "Ehem, semua orang memiliki sedikit dendam meskipun mereka tidak mengatakan apa-apa padamu.",
  ui_story_30460401_9_dialog_content = "Orang dewasa yang bermasalah rambutnya menipis♪",
  ui_story_30460401_10_dialog_content = "Rambutku tidak menipis karena stres! Jangan mengada-ada!",
  ui_story_30460401_11_dialog_content = "Bagaimanapun, kalian selalu mengabaikan orang lain dan mengatakan hal yang aneh tanpa memedulikan orang lain.",
  ui_story_30460401_12_dialog_content = "Jangan bertingkah seperti itu. Setidaknya, <color=#FFB400>aku berharap kalian bisa mendengar perkataan orang lain saat berkomunikasi dengan mereka</color>.",
  ui_story_30460401_13_dialog_content = "Sulit sekali menjadi dirimu. Kamu selalu memikirkan berbagai hal. Kamu tidak bisa melihat jalan keluar saat menengadah, kamu juga tidak bisa melihat jalan saat menunduk.",
  ui_story_30460401_14_dialog_content = "Itu sebabnya aku terus bilang kalau bicara dengan kalian itu sungguh melelahkan...",
  ui_story_30460401_15_option_content = "Bahkan aku tidak tahu yang mana di antara kalian yang berbicara.",
  ui_story_30460401_16_dialog_content = "Kamu harus tahu nama-nama kami.",
  ui_story_30460401_17_dialog_content = "Namun, kami mempertimbangkan waktu responsmu.",
  ui_story_30460401_18_dialog_content = "Itu sebabnya kami mengucapkan kalimat demi kalimat.",
  ui_story_30460401_19_dialog_content = "Untuk memberimu kesempatan.",
  ui_story_30460401_20_dialog_content = "Kamu akan berusaha yang terbaik mulai sekarang, 'kan? Kamu masih butuh kami untuk menjagamu?",
  ui_story_30460401_21_dialog_content = "Aku bisa merasakan ejekan dari cara kalian mengatakan \"menjagamu\".",
  ui_story_30460401_22_option_content = "Aku tidak paham.",
  ui_story_30460401_23_dialog_content = "Apa yang kalian maksud dengan \"kamu tidak bisa melihat jalan saat menunduk\"?",
  ui_story_30460401_24_dialog_content = "Tentu kamu tahu kita mudah tersandung jika tidak memperhatikan ke mana kita pergi.",
  ui_story_30460401_25_dialog_content = "Yang kalian maksud bagaimana aku hampir tersandung ketika berjalan ke sini? Baiklah...",
  ui_story_30460401_26_dialog_content = "Lalu, apa yang kalian maksud dengan \"kamu tidak bisa melihat jalan keluar saat menengadah\"?",
  ui_story_30460401_27_dialog_content = "Kamu sudah punya ide bagus?",
  ui_story_30460401_28_dialog_content = "Apa maksud kalian?",
  ui_story_30460401_29_dialog_content = "Artinya kamu pasti pernah kesulitan.",
  ui_story_30460401_30_dialog_content = "Seperti yang kuduga, kalian menjelaskan, tetapi sebenarnya tidak berniat membuatnya jelas bagi orang lain, ya?",
  ui_story_30460401_31_dialog_content = "Saat orang dewasa bertanya, tentu saja kami harus menjawabnya.",
  ui_story_30460401_32_dialog_content = "Tentu kamu akan paham apa yang kami katakan. Paham, 'kan?",
  ui_story_30460401_33_dialog_content = "Lupakan. Ayo ganti topik. Untuk apa kalian membawakanku hadiah?",
  ui_story_30460401_34_dialog_content = "Sejujurnya, kalian telah mengirimiku begitu banyak pesan dan semuanya membingungkan. Aku hampir tidak bisa memahaminya.",
  ui_story_30460401_35_dialog_content = "Bagaimana bisa kamu begitu cepat meninggalkan pertanyaan yang belum terpecahkan?",
  ui_story_30460401_36_dialog_content = "Lalu beralih memikirkan hadiah yang lebih penting?",
  ui_story_30460401_37_dialog_content = "Namun, sebelum kami membawakan hadiah ini untukmu...",
  ui_story_30460401_38_dialog_content = "<color=#FFB400>Kami ingin bertanya apakah kamu bisa berkomunikasi dengan baik dengan orang-orang.</color>",
  ui_story_30460401_39_dialog_content = "Hmm? Tunggu, kalian yakin justru bukan sebaliknya?",
  ui_story_30460401_40_option_content = "Aku jelas-jelas memberi tahu kalian sebelumnya...",
  ui_story_30460401_41_dialog_content = "Semoga kalian bisa berkomunikasi dengan baik dengan orang lain.",
  ui_story_30460401_42_dialog_content = "Bahasa kita sama.",
  ui_story_30460401_43_dialog_content = "Bagaimana bisa orang dewasa tidak memahami perkataan kami?",
  ui_story_30460401_44_dialog_content = "Sepertinya aku...",
  ui_story_30460401_45_option_content = "Lupakan, anggap saja aku tidak bilang apa-apa.",
  ui_story_30460401_46_dialog_content = "Aku tidak menduga kamu jadi bingung secepat itu sampai-sampai tidak bisa mengekspresikan diri dengan benar.",
  ui_story_30460401_47_dialog_content = "Kamu bilang sesuatu lalu menyangkalnya.",
  ui_story_30460401_48_dialog_content = "Aku hanya...",
  ui_story_30460401_49_dialog_content = "Menurutmu kata-katamu biasanya berbobot?",
  ui_story_30460401_50_dialog_content = "Mengapa kalian tiba-tiba bertanya kepadaku? Kalian bahkan telah menyelaku...",
  ui_story_30460401_51_dialog_content = "Kamu sudah lupa masalahmu?",
  ui_story_30460401_52_dialog_content = "(Meski aku menyarankan semua orang untuk memberi tahu anak-anak apa yang mereka pikirkan secara langsung.)",
  ui_story_30460401_X52_dialog_content = "(Namun, semua orang bilang lebih baik tetap diam.)",
  ui_story_30460401_53_dialog_content = "Hah? Aku tidak sengaja bilang begitu waktu itu?",
  ui_story_30460401_54_dialog_content = "Ya, tetapi kami akan menjagamu.",
  ui_story_30460401_55_dialog_content = "Kamu bilang beberapa orang tidak senang dengan kami.",
  ui_story_30460401_56_dialog_content = "Kamu mengusulkan solusi untuk ini.",
  ui_story_30460401_57_dialog_content = "Namun, orang dewasa lain menolaknya.",
  ui_story_30460401_58_dialog_content = "Jadi, kamu memutuskan untuk memberi tahu kami soal itu atas nama semua orang.",
  ui_story_30460401_59_dialog_content = "Tunggu, aku tidak menganggap semua orang menolak usulanku, atau juga ini ada hubungannya dengan <color=#FFB400>bobot ucapanku</color>.",
  ui_story_30460401_60_dialog_content = "Sayang, jawablah pertanyaan kami. Menurutmu ucapanmu biasanya <color=#FFB400>berbobot</color>?",
  ui_story_30460401_61_option_content = "Tentu saja berbobot!",
  ui_story_30460401_62_dialog_content = "Semua orang mengikuti saranku dalam pertempuran!",
  ui_story_30460401_63_dialog_content = "Apa ini ada hubungannya dengan bobot ucapanmu? Bukankah ini hanya karena semua orang menganggapnya praktis?",
  ui_story_30460401_64_dialog_content = "Kamu bakal marah jika kami bilang begitu?",
  ui_story_30460401_65_option_content = "Tentu saja aku bisa menjawabnya... ucapanku tidak berbobot.",
  ui_story_30460401_66_dialog_content = "Lagi pula, bahkan kalian saja tidak mau mendengarkan aku, kalian juga selalu menyela...",
  ui_story_30460401_67_dialog_content = "Inikah kebiasaanmu saat bicara? Apakah kamu biasanya tersela sepanjang waktu seperti ini?",
  ui_story_30460401_68_dialog_content = "Kamu bakal marah jika kami bilang begitu?",
  ui_story_30460401_69_dialog_content = "Aku tidak sepolos itu untuk membiarkan kalian membuatku marah. Lagi pula, aku sudah terbiasa.",
  ui_story_30460401_70_dialog_content = "Namun, kamu bilang itu sendiri.",
  ui_story_30460401_71_dialog_content = "Banyak orang yang dendam pada kami, 'kan?",
  ui_story_30460401_72_dialog_content = "Tahukah kamu mengapa tidak ada yang mengungkapkan pendapat kepada kami secara blak-blakan sepertimu?",
  ui_story_30460401_73_dialog_content = "Untuk alasan yang sama kami berseragam Lumopolis saat bernyanyi.",
  ui_story_30460401_74_dialog_content = "Memegang kitab suci dan tempat lilin.",
  ui_story_30460401_75_dialog_content = "Menunjukkan reputasi kami sebagai Choir kepada semua orang.",
  ui_story_30460401_76_dialog_content = "Jadi, semua orang akan membiarkan kami melanjutkannya.",
  ui_story_30460401_77_dialog_content = "Tidak akan ada yang keberatan.",
  ui_story_30460401_78_dialog_content = "Itu karena kami memiliki kekuasaan dan status yang membuat kami bisa mengatakan apa pun semaunya.",
  ui_story_30460401_79_dialog_content = "Itu sebabnya sikap mengejek kami ditoleransi.",
  ui_story_30460401_80_dialog_content = "Baiklah, seperti yang kalian bilang, semua orang menolerasi karena kalian adalah Choir.",
  ui_story_30460401_81_dialog_content = "Namun, aku tidak berniat mengintimidasi kalian agar cara kalian berubah.",
  ui_story_30460401_82_dialog_content = "Aku hanya ingin komunikasi dengan setara.",
  ui_story_30460401_83_dialog_content = "Karena kalian banyak bicara, sedikit mendengarkan.",
  ui_story_30460401_84_dialog_content = "Kalian harus menyeimbangkan berbicara dan mendengarkan untuk mencapai keadilan.",
  ui_story_30460401_85_dialog_content = "<color=#FFB400>Kurasa kamu bukan salah satu dari orang-orang arogan sok tahu</color>.",
  ui_story_30460401_86_dialog_content = "Kalau begitu, terimalah hadiah ini dari kami.",
  ui_story_30460401_87_dialog_content = "Halo, PlayerName.",
  ui_story_30460401_88_dialog_content = "Semoga orang-orang selalu membantumu.",
  ui_story_30460401_89_dialog_content = "Semoga orang-orang selalu memberkatimu.",
  ui_story_30460401_90_dialog_content = "Ini adalah berkah dari Lumopolis.",
  ui_story_30460401_91_dialog_content = "Hadiah ini juga mewakili persahabatan Academy, yang kami persembahkan atas namanya.",
  ui_story_30460401_92_dialog_content = "Jadi, hadiahnya adalah berkah ini? Bahkan hadiah yang biasa-biasa saja?!",
  ui_story_30460401_93_dialog_content = "Apa yang harus aku lakukan? Aku tidak tahu kenapa kalian tiba-tiba bilang begitu, tetapi aku merasa kalian sungguh baik.",
  ui_story_30460401_94_dialog_content = "Untuk menjawab pertanyaanmu.",
  ui_story_30460401_95_dialog_content = "Hadiah ini dapat menyelesaikan beberapa masalahmu.",
  ui_story_30460401_96_dialog_content = "Kamu bisa menyebutnya sebagai bobot ucapanmu.",
  ui_story_30460401_97_dialog_content = "Kamu telah <color=#FFB400>diakui dan diberkati secara publik oleh Lumopolis Choir.</color>",
  ui_story_30460401_98_dialog_content = "Mulai sekarang, semua orang akan melihat halo yang menyertai ini ketika melihatmu.",
  ui_story_30460401_99_dialog_content = "Ucapanmu akan menjadi lebih penting dan kamu akan meraih keadilan yang kamu inginkan.",
  ui_story_30460401_100_dialog_content = "Karena kalian bilang begini, itu berarti kalian bersedia mengubah cara kalian berbicara? Kalian bersedia menahan sarkasme dan bersikap lebih manis sebagai gantinya?!",
  ui_story_30460401_101_dialog_content = "Menurutmu kami akan setuju? Menurutmu kami akan berubah untukmu?",
  ui_story_30460401_102_dialog_content = "Apakah orang lain harus berubah hanya karena kamu memintanya?",
  ui_story_30460401_X102_dialog_content = "Menurutmu idemu tentang cara yang lebih baik sungguh lebih baik?",
  ui_story_30460401_103_dialog_content = "Tidak! Lagi-lagi kalian tidak mendengarkan apa yang aku katakan! Apa yang terjadi dengan pengakuan, berkah, dan perhatian yang kalian tunjukkan kepadaku tadi?!",
  ui_story_30460401_104_dialog_content = "Kamu begitu sederhana♫ ♬",
  ui_story_30460401_105_dialog_content = "Kamu begitu naif♪",
  ui_story_30460101_1_dialog_content = "Saat ini aku kesulitan mengerjakan tugas menyusun dokumen tentang Keating.",
  ui_story_30460101_2_dialog_content = "Ada 2 anak laki-laki dan perempuan, tetapi aku sudah bertanya kepada orang-orang dan tidak ada yang bisa membedakan mereka...",
  ui_story_30460101_3_dialog_content = "Sangat sulit untuk menjadi dirimu sendiri, selalu bergumam sendiri, serba licik dan aneh.",
  ui_story_30460101_4_dialog_content = "Sejak kapan aku licik dan aneh?",
  ui_story_30460101_5_dialog_content = "Ketika kamu datang, tubuhmu bungkuk dan kepalamu tertunduk♪ Ketika kamu berpikir, kamu terus mengomel dengan wajah merengut♪",
  ui_story_30460101_6_dialog_content = "Baiklah, kurasa aku mengatakan semuanya tanpa menyadarinya...",
  ui_story_30460101_7_dialog_content = "Kalau begitu, aku akan bertanya langsung kepada kalian...",
  ui_story_30460101_X7_dialog_content = "Siapa di antara kalian berdua yang laki-laki, dan siapa di antara kalian berdua yang perempuan?",
  ui_story_30460101_8_dialog_content = "Karena kamu telah bertanya kepada kami, kami perlu mengujimu terlebih dahulu.",
  ui_story_30460101_9_dialog_content = "Kenapa aku merasa kalian selalu menguji kesabaranku?",
  ui_story_30460101_10_dialog_content = "Ehem, kalian mau mengujiku dengan apa? Silakan saja.",
  ui_story_30460101_11_dialog_content = "Kamu tahu siapa namaku?",
  ui_story_30460101_12_option_content = "Pierre",
  ui_story_30460101_13_dialog_content = "Maaf, tetapi kamu salah.",
  ui_story_30460101_14_dialog_content = "Tidak, tidak, aku tidak mungkin salah. Aku yakin namamu adalah Pierre.",
  ui_story_30460101_15_dialog_content = "Petok, petok.",
  ui_story_30460101_16_dialog_content = "Ayam betina kami berpikir jawabanmu benar.",
  ui_story_30460101_17_dialog_content = "Ayam betina ini benar-benar mengakui hal-hal yang tidak kalian akui?",
  ui_story_30460101_18_dialog_content = "Selain itu, jenis kelamin ayam betina benar-benar jelas.",
  ui_story_30460101_19_dialog_content = "Pertanyaan berikutnya♪",
  ui_story_30460101_20_option_content = "Kara",
  ui_story_30460101_21_dialog_content = "Maaf, tetapi kamu salah.",
  ui_story_30460101_22_dialog_content = "Meski aku tidak benar-benar mau, aku tidak punya pilihan selain menjalani hukuman berharga kami.",
  ui_story_30460101_23_dialog_content = "Maksudku, kamu bahkan tidak tahu namaku...",
  ui_story_30460101_24_dialog_content = "Akankah kalian melakukan sesuatu seperti ini? Apa aku akan dihukum?!",
  ui_story_30460101_25_dialog_content = "Tidak akan.",
  ui_story_30460101_X25_dialog_content = "Kami hanya mengerjaimu.",
  ui_story_30460101_26_dialog_content = "Kamu memercayainya? Begitu saja?",
  ui_story_30460101_27_dialog_content = "Tidak, sebenarnya aku...",
  ui_story_30460101_28_dialog_content = "Pertanyaan berikutnya♪",
  ui_story_30460101_29_dialog_content = "Menurutmu, apa perbedaan antara anak laki-laki dan perempuan dalam paduan suara?",
  ui_story_30460101_30_option_content = "Tidak ada bedanya, 'kan?",
  ui_story_30460101_31_dialog_content = "Kamu tidak memikirkan hal-hal kecil. Kamu luar biasa. Kamu segera mengakhiri percakapan. Kamu hanya ingin kami pergi♪",
  ui_story_30460101_32_dialog_content = "Maaf! Belum selesai, jadi jangan pergi dulu!",
  ui_story_30460101_33_dialog_content = "Kamu belum berpikir dengan cermat tentang apa yang harus ditanyakan♪",
  ui_story_30460101_34_dialog_content = "Kalau begitu, kami hanya bisa membuat Pierre bernyanyi untukmu.",
  ui_story_30460101_35_dialog_content = "Oh♪ semuanya telah usai♪",
  ui_story_30460101_36_dialog_content = "Kalian sungguh ingin mengakhiri ini dengan menyanyikan satu baris? Jangan harap kalian bisa pergi hingga aku selesai bertanya!",
  ui_story_30460101_37_option_content = "Ada perbedaannya, 'kan?",
  ui_story_30460101_38_dialog_content = "Misalnya, bukankah anak perempuan biasanya lebih elegan?",
  ui_story_30460101_39_dialog_content = "Kamu mau kami menjadi tak berbudaya secara sengaja untuk menunjukkan bahwa kami berbeda?",
  ui_story_30460101_40_dialog_content = "Aku tidak pernah berharap kamu membuat permintaan semacam itu. Sayangnya, kami tidak mengumpat sama sekali.",
  ui_story_30460101_41_dialog_content = "Maksudku, tindakan mereka lebih elegan!",
  ui_story_30460101_42_dialog_content = "Kami bisa membuktikan tidak ada perbedaan di antara kami dalam hal ini dengan menari.",
  ui_story_30460101_43_dialog_content = "Tarian aneh macam apa ini? Kenapa kalian terlihat seperti sekadar bergoyang ke kiri dan ke kanan?",
  ui_story_30460101_44_dialog_content = "Ini tidak lagi berhubungan dengan keeleganan. Kenyataannya, ini terlihat memalukan!",
  ui_story_30460101_45_dialog_content = "Sepertinya kamu masih belum puas dengan jawaban kami. Apa yang harus kami lakukan agar kamu puas?",
  ui_story_30460101_46_dialog_content = "Jangan bilang seperti itu. Kalian membuatnya terdengar seolah-olah aku memaksa kalian untuk melakukan sesuatu...",
  ui_story_30460101_47_dialog_content = "Aku ingin tahu jenis kelamin kalian masing-masing...",
  ui_story_30460101_48_dialog_content = "Kami akan memberitahumu jawaban yang kamu mau jika kamu bisa menjawab pertanyaan terakhir kami♪",
  ui_story_30460101_49_dialog_content = "Baik, bertanyalah. Namun, pertanyaan kalian harus mudah dipahami!",
  ui_story_30460101_50_dialog_content = "Tentu saja. Simak baik-baik♪",
  ui_story_30460101_51_dialog_content = "<color=#FFFFFF><size=35>(Niel) Saya tahu bahwa dua dari tiga lainnya adalah laki-laki.</size></color>",
  ui_story_30460101_52_dialog_content = "<color=#FFFFFF><size=35>(Kara) Aku tahu Pierre adalah anak laki-laki.</size></color>",
  ui_story_30460101_53_dialog_content = "<color=#FFFFFF><size=35>(Pierre) Aku tahu Dian adalah anak laki-laki.</size></color>",
  ui_story_30460101_54_dialog_content = "<color=#FFFFFF><size=35>(Dian) Aku tahu aku ini anak perempuan.</size></color>",
  ui_story_30460101_55_dialog_content = "<color=#FFFFFF><size=35>(Pierre) Saya tahu bahwa anak laki-laki mengatakan yang sebenarnya, dan anak perempuan berbohong.</size></color>",
  ui_story_30460101_56_dialog_content = "Bisa jadi seperti yang Pierre bilang, atau malah sebaliknya.",
  ui_story_30460101_57_dialog_content = "Sekarang, kamu tahu siapa di antara kami yang laki-laki dan siapa yang perempuan?",
  ui_story_30460101_58_dialog_content = "Ini... Jika aku bisa menjawabnya, kalian tidak perlu memberitahukan jawabannya, oke?!",
  ui_story_30460101_59_dialog_content = "Apakah kamu akhirnya akan berhenti? Apakah kamu akhirnya akan menyerah?",
  ui_story_30460101_60_dialog_content = "Tunggu! Aku tahu 2 di antara kalian adalah laki-laki dan 2 di antara kalian adalah perempuan...",
  ui_story_30460101_61_dialog_content = "Sesuai dengan apa yang baru saja kalian katakan, 2 di antara kalian pasti berkata jujur dan 2 lainnya berkata bohong. Aku benar, 'kan?",
  ui_story_30460101_62_dialog_content = "Ya.",
  ui_story_30460101_63_dialog_content = "Kami akan membantumu dengan mengajukan pertanyaan yang lebih sederhana.",
  ui_story_30460101_X63_dialog_content = "Apakah Niel laki-laki atau perempuan?",
  ui_story_30460101_64_option_content = "Niel adalah laki-laki.",
  ui_story_30460101_65_dialog_content = "Kamu hanya beruntung, atau kamu sudah tahu jawabannya?",
  ui_story_30460101_66_dialog_content = "Ehem, ini tidak penting. Yang penting adalah, apakah aku benar?",
  ui_story_30460101_67_dialog_content = "Kamu benar.",
  ui_story_30460101_68_dialog_content = "Tidak, kamu salah.",
  ui_story_30460101_69_dialog_content = "Apa???",
  ui_story_30460101_70_option_content = "Niel adalah perempuan.",
  ui_story_30460101_71_dialog_content = "Sebenarnya, Niel adalah laki-laki.",
  ui_story_30460101_72_dialog_content = "Apa?! Namun, Niel punya karakteristik yang halus dan terlihat sangat elegan!",
  ui_story_30460101_73_dialog_content = "Kamu bilang kami tidak punya karakteristik yang halus?",
  ui_story_30460101_74_dialog_content = "Bagaimana kalian bisa menyimpulkan seperti itu?!",
  ui_story_30460101_75_dialog_content = "Jadi, apakah Niel benar-benar laki-laki?",
  ui_story_30460101_76_dialog_content = "Tidak, Niel adalah perempuan.",
  ui_story_30460101_77_dialog_content = "Apa???",
  ui_story_30460101_78_dialog_content = "Ini tidak akan berhasil. Kalian membuatku bingung lagi. Beri tahukan saja jawabannya. Kita sudah sepakat.",
  ui_story_30460101_79_dialog_content = "Kamu tidak ingat apa yang Pierre bilang?",
  ui_story_30460101_80_dialog_content = "Aku ingat. Aku menjawab, dan Pierre seharusnya memberitahuku jawabannya jika aku menjawab!",
  ui_story_30460101_81_dialog_content = "Kami akan memberitahumu jawaban yang kamu mau jika kamu bisa menjawab pertanyaan terakhir kami♪",
  ui_story_30460101_82_dialog_content = "Oh♪ kamu kira kamu akan mendapatkan sesuatu secara gratis? Itu akan terlalu idealistis dan terlalu mudah♪",
  ui_story_30460101_83_dialog_content = "Kalian tidak bilang apakah jawabanku benar atau tidak, tetapi aku tidak keberatan karena kalian tidak bilang bahwa jawabanku harus benar.",
  ui_story_30460101_84_dialog_content = "Maaf, kami tidak pernah berniat memberitahumu secara langsung.",
  ui_story_30460101_85_dialog_content = "Namun...",
  ui_story_30460101_86_dialog_content = "Selain itu, ada satu hal lagi yang ingin kami beri tahukan.",
  ui_story_30460101_87_dialog_content = "Aku tahu anak laki-laki berkata jujur dan anak perempuan berkata bohong.",
  ui_story_30460101_88_dialog_content = "Bisa jadi seperti yang Pierre bilang, atau malah sebaliknya.",
  ui_story_30460101_89_dialog_content = "Ini mungkin tidak selalu terjadi, <color=#FFB400>tetapi seseorang juga mengatakan kebohongan yang sangat jelas.</color>",
  ui_story_30460101_90_dialog_content = "<color=#FFB400>Namun, seseorang memberitahumu kejujuran yang jelas juga.</color>",
  ui_story_30460101_91_dialog_content = "Pikirkan baik-baik.",
  ui_story_30460101_92_dialog_content = "Gunakan petunjuk terakhirmu.",
  ui_story_30460101_93_dialog_content = "Jika kamu masih belum tahu <color=#FFB400>siapa di antara kami yang laki-laki dan yang perempuan.</color>",
  ui_story_30460101_94_dialog_content = "Pikirkan sendiri. Gali lebih dalam ingatanmu hingga rambutmu mulai rontok♪",
  ui_story_30460101_95_dialog_content = "Aku akan melakukannya, tetapi rambutku tidak akan rontok hanya karena aku berusaha keras untuk mengingat! Jangan mengada-ada!",
  ui_story_30460201_1_dialog_content = "...",
  ui_story_30460201_2_dialog_content = "City Lord, sepertinya suasana hatimu sedang buruk. Sesuatu terjadi?",
  ui_story_30460201_3_dialog_content = "PlayerName tersayang kami ada di sini♪",
  ui_story_30460201_4_dialog_content = "Kamu bergerak perlahan dan menimbang ucapanmu; apakah kamu dimarahi, atau apakah kamu kabur terkaing-kaing?",
  ui_story_30460201_5_dialog_content = "Ehem, aku tentunya senang kamu menyapaku.",
  ui_story_30460201_6_dialog_content = "Namun, jelas bahwa City Lord kecewa dengan kalian semua, jadi berhentilah bermain-main.",
  ui_story_30460201_7_dialog_content = "Seseorang memberiku bunga...",
  ui_story_30460201_8_dialog_content = "Bu-bukankah itu hal yang bagus?",
  ui_story_30460201_9_dialog_content = "Di Lounge, seseorang menaruh bunga di belakang telingaku ketika aku sedang beristirahat...",
  ui_story_30460201_10_option_content = "Mungkinkah itu Keating?",
  ui_story_30460201_11_dialog_content = "Apakah itu sebabnya kamu menatap tajam Keating? Karena ini?",
  ui_story_30460201_12_dialog_content = "Oh, PlayerName tersayang, hanya ada City Lord di matamu, bukannya kami♪",
  ui_story_30460201_13_dialog_content = "Kalian masih bernyanyi?! Kalian tidak peduli City Lord mungkin akan murka?",
  ui_story_30460201_14_dialog_content = "...",
  ui_story_30460201_15_dialog_content = "Sikapnya tidak berubah, tetapi siapa bilang dia tidak akan murka?",
  ui_story_30460201_16_option_content = "Siapa yang berani?!",
  ui_story_30460201_17_dialog_content = "Maksudku, siapa yang berani mengerjai City Lord?!",
  ui_story_30460201_18_dialog_content = "Tidak ada orang lain yang berani selain anak-anak ini.",
  ui_story_30460201_19_dialog_content = "City Lord, kamu marah?",
  ui_story_30460201_20_dialog_content = "PlayerName tersayang bicara begitu lantang saat menyanjung orang lain. PlayerName tersayang jelas mencoba untuk menarik perhatian seseorang♪",
  ui_story_30460201_21_dialog_content = "...",
  ui_story_30460201_22_dialog_content = "Kalian berkelakar dan kemudian memiliki nyali untuk bertanya apakah aku marah?",
  ui_story_30460201_23_dialog_content = "Marah? Karena kamu ada di sini, mengapa kamu tidak meredakan kemarahan ini?",
  ui_story_30460201_24_dialog_content = "Anak muda, kamulah master Colossus. Ini wilayahmu, jadi kamu harus memutuskan.",
  ui_story_30460201_25_dialog_content = "Aku tahu. Kalau begitu, bolehkah aku membuat rekaman tentang ini?",
  ui_story_30460201_26_dialog_content = "Aku hanya ingin merekam semua insiden besar yang terjadi di Colossus.",
  ui_story_30460201_27_dialog_content = "Rekaman khusus eksklusif untuk Colossus? Baiklah, kuizinkan.",
  ui_story_30460201_28_dialog_content = "<size=70>Berita Colossus</size>",
  ui_story_30460201_29_dialog_content = "<color=#FFB400>Insiden Bunga Keating</color> terjadi di Colossus hari ini. Mari kita lihat lebih dekat.",
  ui_story_30460201_30_dialog_content = "Ini berdasarkan pada adegan dan narasi Schwartz the City Lord.",
  ui_story_30460201_31_dialog_content = "Bisa dibilang dia jelas mencurigai kuartet Keating...",
  ui_story_30460201_32_dialog_content = "Kamu... Ini adalah cara merekam sesuatu yang agak beda.",
  ui_story_30460201_33_dialog_content = "Ehem, Vice dan aku yang punya ide ini...",
  ui_story_30460201_34_dialog_content = "Kami menemukan metode perekaman baru ini setelah mengacu ke berbagai sumber informasi, dan saat ini kami sedang mengujinya.",
  ui_story_30460201_35_dialog_content = "Semua rekaman insiden akan dilampirkan dengan penjelasan yang terperinci dan dinamis, membuatnya akurat dan mudah dibaca.",
  ui_story_30460201_36_dialog_content = "PlayerName tersayang♪ kamu tidak membiarkan Keating berbicara♪",
  ui_story_30460201_37_dialog_content = "Apakah kamu mencoba mengucilkan kami? Apakah kamu hanya ingin bermain dengan City Lord?",
  ui_story_30460201_38_dialog_content = "Maaf, biarkan aku membuat rekaman deskriptif dulu.",
  ui_story_30460201_39_dialog_content = "Mari kita mulai secara resmi. Aku akan segera memintamu berbicara.",
  ui_story_30460201_40_dialog_content = "Untuk rekaman ini, kamu harus <color=#FFB400>memperhatikan formalitas kata-katamu dan efek tampilannya.</color>",
  ui_story_30460201_41_dialog_content = "Sudah cukup penjelasannya. Kita mulai saja...",
  ui_story_30460201_42_dialog_content = "Kenyataannya, pihak yang diduga oleh penggugat tampaknya tidak puas dengan kesimpulannya.",
  ui_story_30460201_43_dialog_content = "Siapa? Apa?",
  ui_story_30460201_44_dialog_content = "Ya, kalian melakukannya. Kalian menaruh bunga ini di belakang telingaku ketika aku beristirahat.",
  ui_story_30460201_45_dialog_content = "Ini salah paham.",
  ui_story_30460201_46_dialog_content = "Kamu marah karena salah mengira bunga itu adalah lelucon.",
  ui_story_30460201_47_dialog_content = "Namun, seharusnya kamu jangan marah.",
  ui_story_30460201_48_dialog_content = "Kenapa?",
  ui_story_30460201_49_dialog_content = "Karena persembahan bunga melambangkan rasa hormat.",
  ui_story_30460201_50_dialog_content = "Itulah yang diajarkan <color=#FFB400>Uriah</color> kepada kami.",
  ui_story_30460201_51_dialog_content = "Maaf, kalau aku menyela. Boleh aku bertanya?",
  ui_story_30460201_52_dialog_content = "Aku akan mencatat semuanya di catatan rekaman.",
  ui_story_30460201_53_dialog_content = "PlayerName, kamu ingin bertanya? Bertanyalah♪",
  ui_story_30460201_54_option_content = "Tanyakan tentang bunga itu.",
  ui_story_30460201_55_dialog_content = "Bagaimana kalian mendapatkan bunga putih di Colossus ini?",
  ui_story_30460201_56_dialog_content = "Kamu masih belum tahu, kamu tidak tahu harus bertanya apa♪",
  ui_story_30460201_57_dialog_content = "Ini hanyalah bunga putih spesial yang ditanam <color=#FFB400>kakak perempuan</color> bersama Lumina-nya. Bunga ini mekar karena sihir <color=#FFB400>kakak perempuan</color>♪",
  ui_story_30460201_58_dialog_content = "Baiklah, aku akan mencatatnya.",
  ui_story_30460201_59_option_content = "Tanyakan tentang kakak perempuan.",
  ui_story_30460201_60_dialog_content = "Dia adalah <color=#FFB400>Uriah</color> yang kami sayang, senior kami tercinta dari Academy♪",
  ui_story_30460201_61_dialog_content = "Dia mengajari kami cara berbicara, dan cara bernyanyi untuk para bangsawan♪",
  ui_story_30460201_62_dialog_content = "Itu informasi yang menarik.",
  ui_story_30460201_63_dialog_content = "Begitu, ya. Aku telah mencatatnya.",
  ui_story_30460201_64_dialog_content = "Selain itu, mengapa aku merasa kalian kurang sopan kepada City Lord?",
  ui_story_30460201_65_dialog_content = "Konflik seperti ini dapat menambahkan drama pada rekaman.",
  ui_story_30460201_66_dialog_content = "Namun, aku sudah lama ingin bertanya pada kalian. Cara kalian berbicara dengan City Lord...",
  ui_story_30460201_67_option_content = "Menurut kalian bermasalah?",
  ui_story_30460201_68_dialog_content = "Kami sangat menghormati♪ City Lord yang terkasih♪",
  ui_story_30460201_69_dialog_content = "Jelas kami memperlakukannya secara berbeda dibandingkan denganmu, PlayerName♪",
  ui_story_30460201_70_dialog_content = "Haha, dibandingkan dengan cara mereka memperlakukan bangsawan lain, sebenarnya mereka cukup sopan padamu.",
  ui_story_30460201_71_dialog_content = "Tunggu, bukankah baru saja aku berbicara mewakili City Lord?",
  ui_story_30460201_72_dialog_content = "Mengapa aku merasa akulah yang sedang diserang?",
  ui_story_30460201_73_dialog_content = "City Lord jelas menyukai kami dan mengetahui kepribadian kami dengan baik.",
  ui_story_30460201_74_dialog_content = "Aku paham, jadi begini rasanya didukung oleh seseorang yang berkuasa...",
  ui_story_30460201_75_option_content = "Tuan keberatan?",
  ui_story_30460201_76_dialog_content = "Hanya ucapan bandel dari beberapa anak. Tentu saja, aku tidak akan menganggapnya serius.",
  ui_story_30460201_77_dialog_content = "City Lord memilih kami secara pribadi.",
  ui_story_30460201_78_dialog_content = "City Lord tahu anak macam apa kami dan mengizinkan kami bergabung dengan Choir.",
  ui_story_30460201_79_dialog_content = "Benarkah itu?",
  ui_story_30460201_80_dialog_content = "Karena aku yang membuat keputusan ini, jelas sifat mereka memiliki tujuan tertentu bagiku.",
  ui_story_30460201_81_dialog_content = "Tidak heran mereka sulit diatur! Ini pasti bagaimana rasanya didukung oleh penguasa...",
  ui_story_30460201_82_dialog_content = "Baik, karena City Lord tidak keberatan, aku akan terus merekam konflik dramatis kalian seperti ini.",
  ui_story_30460201_83_dialog_content = "Kita lanjutkan rekaman. 3, 2, 1... Action—",
  ui_story_30460201_84_dialog_content = "Beginikah cara kalian mempersembahkan bunga? Dengan menempelkannya di belakang telinga orang?",
  ui_story_30460201_85_dialog_content = "Karena memang cantik seperti itu.",
  ui_story_30460201_86_dialog_content = "Karena memang elegan seperti itu.",
  ui_story_30460201_87_dialog_content = "Omong kosong.",
  ui_story_30460201_88_dialog_content = "Karena itu benar.",
  ui_story_30460201_89_dialog_content = "Benar? Kalau begitu, sebaiknya kalian punya cukup bukti untuk mendukung itu.",
  ui_story_30460201_90_dialog_content = "Sebenarnya, kakak tersayang kami, Uriah, juga melakukan hal yang serupa kepada kami.",
  ui_story_30460201_91_dialog_content = "Dia akan memberkati kami dengan senyuman dan menaruh bunga yang indah di belakang telinga kami.",
  ui_story_30460201_92_dialog_content = "Itulah yang kami pelajari. Itulah yang kami tahu.",
  ui_story_30460201_93_dialog_content = "Hmmm, jadi sekarang kalian berniat melemparkan tanggung jawab ini kepada orang lain?",
  ui_story_30460201_94_dialog_content = "Maaf, aku menyela lagi. Bukankah ada sedikit tumpang tindih dengan apa yang kamu bilang tadi?",
  ui_story_30460201_95_dialog_content = "PlayerName tersayang, kamu selalu menyela orang.",
  ui_story_30460201_96_dialog_content = "City Lord sangat sibuk.",
  ui_story_30460201_97_dialog_content = "Seharusnya hanya ada beberapa pertanyaan.",
  ui_story_30460201_98_dialog_content = "Namun, pertanyaannya diperpanjang tanpa batas.",
  ui_story_30460201_99_dialog_content = "Ini telah menjadi masalah yang lebih besar♪",
  ui_story_30460201_100_dialog_content = "Aku tidak keberatan, tetapi kamu memang harus mencatat ini. Waktuku terbatas, jadi mari kita akhiri ini dengan cepat.",
  ui_story_30460201_101_dialog_content = "Maaf, aku akan menyuntingnya setelah merekam hal-hal yang kita katakan selanjutnya. Katakanlah sesuatu sebagai kesimpulan.",
  ui_story_30460201_102_dialog_content = "3, 2, 1... Action—",
  ui_story_30460201_103_dialog_content = "Kami tidak menghindari tanggung jawab—kami hanya menyatakan kebenaran.",
  ui_story_30460201_104_dialog_content = "Lagi pula, kami hanya anak-anak. Kenapa kamu yang repot?",
  ui_story_30460201_105_dialog_content = "Kalian memang anak-anak, tetapi kalian harus diberi pelajaran jika perlu.",
  ui_story_30460201_106_dialog_content = "Anak-anak tidak boleh dimanja.",
  ui_story_30460201_107_dialog_content = "Mulai sekarang, situasinya menjadi jelas.",
  ui_story_30460201_108_dialog_content = "Meski masih anak-anak, Keating mengeklaim bahwa mereka tidak pernah berkelakar...",
  ui_story_30460201_109_dialog_content = "Lord Schwartz berniat untuk membuat mereka bertanggung jawab setelah ini.",
  ui_story_30460201_110_dialog_content = "Ini adalah laporan rekaman yang disiapkan oleh PlayerName, reporter Colossus.",
  ui_story_30460201_111_dialog_content = [[
Navigator: PlayerName
Wartawan di tempat: PlayerName
Orang yang hadir: Niel, dari Keating Paduan suara
 Kara, dari Keating Paduan suara
 Pierre, dari Keating Paduan suara
 Dian, dari Keating Paduan suara
 Yang mulia Schwartz, Penguasa Kota Lumopolis]],
  ui_story_30460201_112_dialog_content = "Sungguh menarik. Laporan ini lumayan juga.",
  ui_story_30460201_113_dialog_content = "Terima kasih atas dukunganmu, City Lord. Pidatomu sungguh sempurna.",
  ui_story_30460201_114_dialog_content = "Meski insiden tersebut direkam secara berbeda dari rekaman di Lumopolis, kamu tidak perlu khawatir karena aku bisa memahaminya.",
  ui_story_30460201_115_dialog_content = "Kalau begitu, masalah ini selesai sudah. Ada hal lain yang perlu kuurus sekarang.",
  ui_story_30460201_116_dialog_content = "Hati-hati, City Lord.",
  ui_story_30460201_117_dialog_content = "Halo, PlayerName, kamu mengabaikan kami dan lagi-lagi hanya bicara kepada City Lord.",
  ui_story_30460201_118_dialog_content = "PlayerName mencoba bersikap hormat,",
  ui_story_30460201_119_dialog_content = "tetapi pilihan kata-katanya aneh.",
  ui_story_30460201_120_dialog_content = "Gagal sudah.",
  ui_story_30460201_121_dialog_content = "Seharusnya kalian sedikit lebih pengertian karena bahkan City Lord saja tidak bilang apa-apa.",
  ui_story_30460201_122_dialog_content = "Aku belum pernah belajar etiket istana, jadi aku sudah mencoba yang terbaik untuk bersikap hormat.",
  ui_story_30460201_123_dialog_content = "Dalam rekaman, City Lord juga bilang untuk tidak memanjakan kalian, anak-anak.",
  ui_story_30460201_124_dialog_content = "Namun, aku merasa dia masih cukup toleran pada kalian.",
  ui_story_30460201_125_dialog_content = "Ya, memang.",
  ui_story_30460601_1_dialog_content = "\"Begitu kamu membuka Buku Sihir Hitam ini,\"",
  ui_story_30460601_2_dialog_content = "\"Kamu akan dipindahkan ke dunia baru yang misterius.\"",
  ui_story_30460601_3_dialog_content = "\"Dunia keajaiban dan keajaiban,\"",
  ui_story_30460601_4_dialog_content = "\"Penuh dengan segala macam hal yang luar biasa.\"",
  ui_story_30460601_5_dialog_content = "\"Dunia untuk jiwa-jiwa yang ingin tahu dan kesepian.\"",
  ui_story_30460601_6_dialog_content = "Bagaimana menurutmu? Intro buku ini benar-benar tahu cara menarik perhatian pembaca, ya?",
  ui_story_30460601_7_dialog_content = "Apa ini \"Tome of Black Magic\" juga alasan kalian berdandan seperti ini?",
  ui_story_30460601_8_dialog_content = "Saya dapat meyakinkan Anda, teman saya yang bodoh dan dewasa, bahwa buku ini berisi ilmu hitam yang nyata dan terlarang.",
  ui_story_30460601_9_dialog_content = "Dan Anda mengatakan seorang wanita aneh di jalan memberikan ini kepada Anda?",
  ui_story_30460601_10_dialog_content = "Apa kau yakin dia tidak berbohong?",
  ui_story_30460601_11_dialog_content = "Tidak seperti Anda, kami tidak mudah dibodohi.",
  ui_story_30460601_12_dialog_content = "Dia terus bercerita tentang betapa menakutkannya buku itu!",
  ui_story_30460601_13_dialog_content = "Saya yakin dia hanya melakukan itu untuk mendapatkan perhatian Anda.",
  ui_story_30460601_14_dialog_content = "Dia juga mengatakan bahwa buku ini hanya menakutkan untuk orang dewasa. Untuk anak kecil seperti kita, ini sangat aman!",
  ui_story_30460601_15_dialog_content = "Kamu bercanda kan? Dia jelas menipu Anda untuk membeli buku ini!",
  ui_story_30460601_16_dialog_content = "Berapa banyak Anda membayarnya? Ayo, saya akan membantu Anda mendapatkan uang Anda kembali!",
  ui_story_30460601_17_dialog_content = "Dia tidak menginginkan uang kita.",
  ui_story_30460601_18_dialog_content = "Hah? Jadi itu gratis ...",
  ui_story_30460601_19_dialog_content = "Apakah Anda pikir masih ada masalah sekarang?",
  ui_story_30460601_20_option_content = "Kalau gratis, saya kira tidak.",
  ui_story_30460601_21_dialog_content = "♫ Berhemat adalah kebohongan yang disembunyikan orang dewasa, keserakahan mengerikan yang mereka simpan di dalam!♪",
  ui_story_30460601_22_dialog_content = "A-aku hanya menyimpannya karena penasaran!",
  ui_story_30460601_23_option_content = "Lagi pula, tidak ada yang gratis dalam hidup, lho!",
  ui_story_30460601_24_dialog_content = "♫Dan pada akhirnya, uang masih mengatur semua permainan yang mereka mainkan!♪",
  ui_story_30460601_25_dialog_content = "Ya, ya, silakan berpikir apa pun yang Anda inginkan.",
  ui_story_30460601_26_dialog_content = "Jadi, buku macam apa ini?",
  ui_story_30460601_27_dialog_content = "Saya kira tidak ada salahnya membiarkan Anda melihatnya.",
  ui_story_30460601_28_dialog_content = "Jika ada, Anda mungkin bisa membantu.",
  ui_story_30460601_29_dialog_content = "Itu adalah buku sihir terlarang kuno. Sebagian besar sudah hilang.",
  ui_story_30460601_30_dialog_content = "Tapi di halaman terakhir...",
  ui_story_30460601_31_dialog_content = "\"Nama: Titanic Monster...\"",
  ui_story_30460601_32_dialog_content = "(Huh, sisanya tidak bisa dikenali.)",
  ui_story_30460601_33_dialog_content = "Bahan: pare, seledri, paprika hijau...",
  ui_story_30460601_34_dialog_content = "Tunggu, ini hanya bahan masakan biasa!",
  ui_story_30460601_35_dialog_content = "Anda mungkin ingin melihat baris berikutnya.",
  ui_story_30460601_36_dialog_content = "Tentakel coleoid, Koppia Caterpillar mucus, Mackerel fins.",
  ui_story_30460601_37_dialog_content = "Uhh... Apa-apaan ini?",
  ui_story_30460601_38_dialog_content = "Beberapa bahan daging yang lengket dan tidak diketahui asalnya, rupanya.",
  ui_story_30460601_39_dialog_content = "Sekarang apakah Anda percaya buku ini penuh dengan ilmu hitam?",
  ui_story_30460601_40_dialog_content = "(Saya cukup yakin itu hanya resep yang aneh, tapi mungkin menakutkan untuk anak kecil seperti mereka. Mungkin saya harus bermain bersama untuk saat ini...)",
  ui_story_30460601_41_dialog_content = "Memang benar, ada sesuatu yang menakutkan tentang materi yang tercantum di sini...",
  ui_story_30460601_42_dialog_content = "Hanya membacanya dengan keras membuat Anda merinding.",
  ui_story_30460601_43_dialog_content = "Lihatlah, ini adalah dongeng Caelestite. Betapa \"legendaris\" Anda!",
  ui_story_30460601_44_dialog_content = "Aku tidak akan bercanda terlalu banyak, guys. Bagaimana jika mantra ini benar-benar bisa memanggil monster yang besar dan mengerikan?",
  ui_story_30460601_45_dialog_content = "Itu akan luar biasa!",
  ui_story_30460601_46_dialog_content = "Ayo berpencar dan cari bahan-bahan itu!",
  ui_story_30460601_47_dialog_content = "Keluar, semuanya!",
  ui_story_30460601_48_dialog_content = "Tunggu, kalian serius tentang ini?",
  ui_story_30460601_49_dialog_content = "Tapi bagaimana jika...",
  ui_story_30460601_50_dialog_content = "Pengecut ditakdirkan untuk bersembunyi di balik layar.",
  ui_story_30460601_51_dialog_content = "Hanya yang pemberani yang diberkati dengan keajaiban!",
  ui_story_30460601_52_dialog_content = "(Itu cukup mudah bagimu untuk mengatakannya, tapi aku tidak akan bisa diam saja jika sesuatu benar-benar terjadi.)",
  ui_story_30460601_53_dialog_content = "Jika Anda ingin membuktikan sendiri, Anda harus memberi kami tempat untuk mencampur bahan-bahan ini.",
  ui_story_30460601_54_dialog_content = "Hah? Mengapa saya?",
  ui_story_30460601_55_dialog_content = "(Heh, saya tahu mereka membutuhkan saya! Silakan, beri tahu saya betapa pentingnya saya!)",
  ui_story_30460601_56_dialog_content = "Karena jika Anda tidak membantu, kami tidak punya pilihan selain menggunakan ramuan itu pada Anda.",
  ui_story_30460601_57_dialog_content = "Siapa tahu, Anda bahkan mungkin terbangun dengan monster raksasa di kamar Anda!",
  ui_story_30460601_58_dialog_content = "Jadi sekarang kau mengancamku?!",
  ui_story_30460601_59_dialog_content = "Saya yakin orang dewasa menyebutnya \"quid pro quo\"?",
  ui_story_30460601_60_dialog_content = "Jangan hanya melontarkan kata-kata ketika Anda tidak benar-benar tahu apa artinya!",
  ui_story_30460601_61_dialog_content = "(Aku berencana membantu mereka dari awal, tapi sekarang sepertinya aku terpaksa melakukannya...)",
  ui_story_30460601_62_dialog_content = "Ada panci besar di dapur. Anda dapat menggunakannya sebagai \"kuali\" Anda.",
  ui_story_30460601_63_dialog_content = "Anda terlalu melebih-lebihkan kekuatan peralatan dapur Anda.",
  ui_story_30460601_64_dialog_content = "Selain itu, kami tidak ingin merusak Colossus dengan cara apa pun.",
  ui_story_30460601_65_dialog_content = "Apakah kalian benar-benar yakin ingin membuat monster raksasa?",
  ui_story_30460601_66_dialog_content = "Tentu kami! Bagaimana seekor elang bisa terbang tinggi tanpa ambisinya mengaum?",
  ui_story_30460601_67_dialog_content = "Baiklah, kalau begitu aku akan pergi bertanya Carleen jika ada laboratorium terbengkalai di Lumopolis untuk Anda gunakan.",
  ui_story_30460601_68_dialog_content = "Meskipun kami tidak terlalu percaya pada kemampuan Anda untuk menyelesaikan sesuatu...",
  ui_story_30460601_69_dialog_content = "Dengan Nona Carleen di pihak kita, kita seharusnya tidak perlu khawatir!",
  ui_story_30460601_70_dialog_content = "Sekarang mari kita mulai bekerja!",
  ui_story_30460601_71_dialog_content = "Sampai jumpa lagi!",
  ui_story_30460601_72_dialog_content = "Apa aku salah dengar, sayang? Anda ingin pare, seledri, dan paprika hijau?",
  ui_story_30460601_73_dialog_content = "Saya pikir Anda selalu membenci hal-hal ini.",
  ui_story_30460601_74_dialog_content = "Anda benar sekali, ibuku sayang.",
  ui_story_30460601_75_dialog_content = "Namun di sini Anda meminta sayuran sehat itu! Mama sangat bangga padamu, Niel!",
  ui_story_30460601_76_dialog_content = "Saya akan membiarkan staf dapur mengemasi Anda tas besar sekarang, oke?",
  ui_story_30460601_77_dialog_content = "Terima kasih mama. Tolong jangan tambahkan yang lain juga.",
  ui_story_30460601_78_dialog_content = "Niel kecilku akhirnya belajar makan sayur! Aku sangat bahagia!",
  ui_story_30460601_79_dialog_content = "Apa ini cukup?",
  ui_story_30460601_80_dialog_content = "Ya, mama. Sekarang, aku harus pergi sebelum air matamu mulai membanjiri rumah.",
  ui_story_30460601_81_dialog_content = "Sebelum Anda pergi, izinkan saya meminta koki memasak sesuatu untuk Anda. Bagaimana rasanya pare isi seledri ditambah sepiring paprika hijau goreng dengan peterseli?",
  ui_story_30460601_82_dialog_content = "Aku ingin melihatmu memakan semuanya!",
  ui_story_30460601_83_dialog_content = "Aku menghargai perhatiannya, tapi aku tidak terlalu lapar sekarang, mama.",
  ui_story_30460601_84_dialog_content = "Tapi itu akan membantu Anda tumbuh besar dan kuat! Cobalah gigitan!",
  ui_story_30460601_85_dialog_content = "Kubiarkan saja kamu menikmati makanan enak dan bergizi ini, mama! Aku benar-benar harus pergi sekarang! Selamat tinggal!",
  ui_story_30460601_86_dialog_content = "Astaga, dia lari begitu cepat! Lagipula, Niel kecilku pasti sedang makan sayurannya!",
  ui_story_30460601_87_dialog_content = "Oke, selesai! Mulai sekarang, semua makanan di rumah ini harus menyertakan sayuran ini!",
  ui_story_30460601_88_dialog_content = "Saya telah mencari di setiap buku, tetapi tetap tidak ada!",
  ui_story_30460601_89_dialog_content = "Kara? Apakah Anda mencari sesuatu yang khusus?",
  ui_story_30460601_90_dialog_content = "Ya, profesor. Saya sedang mencari buku tentang biologi kelautan.",
  ui_story_30460601_91_dialog_content = "Itu mata pelajaran yang sama yang saya ajarkan! Ha ha ha ha! Sejak kapan kamu begitu tertarik dengan bidang ini, Kara?",
  ui_story_30460601_92_dialog_content = "Nah, saya mencoba untuk belajar lebih banyak tentang makhluk yang disebut \"Coleoid\". Anda pasti tahu semua tentang itu, karena Anda menghabiskan seluruh hidup Anda untuk meneliti hewan laut, bukan?",
  ui_story_30460601_93_dialog_content = "Memang, tidak ada seorang pun di Akademi yang memiliki lebih banyak pengetahuan tentang hal ini daripada saya. Bahkan, saya bahkan menyimpan beberapa tentakel Coleoid di kantor saya!",
  ui_story_30460601_94_dialog_content = "Orang yang lebih tua pasti suka mengarang cerita yang tidak pernah ada saat mereka masih muda, bukan?",
  ui_story_30460601_95_dialog_content = "Aku tidak mengada-ada, Kara! Tentakelnya ada di lemariku! Jika saya ingat dengan benar, tiga puluh tahun yang lalu ...",
  ui_story_30460601_96_dialog_content = "Jika Anda akan tersesat dalam ingatan Anda, profesor. Bisakah Anda setidaknya melompat ke bagian yang penting?",
  ui_story_30460601_97_dialog_content = "Er, b-baiklah kalau begitu. Di masa muda saya, saya menemukan seorang wanita cantik saat meneliti spesimen yang berbeda di dekat laut...",
  ui_story_30460601_98_dialog_content = "Biar kutebak: kamu jatuh cinta, tapi dia tidak merasakan hal yang sama?",
  ui_story_30460601_99_dialog_content = "Y-Ya, itu benar. Ngomong-ngomong, saya menemukan gua karst tepi laut tak lama kemudian, dan di dalam gua itu...",
  ui_story_30460601_100_dialog_content = "Semakin lama sebuah cerita berlarut-larut, semakin buruk akhirnya.",
  ui_story_30460601_101_dialog_content = "Saya menemukan ini! Melihat? Tentakel coleoid, seperti yang saya katakan!",
  ui_story_30460601_102_dialog_content = "Maka, pahlawan pemberani akhirnya mengklaim harta karun itu.",
  ui_story_30460601_103_dialog_content = "Saya sangat setuju! Bagaimanapun, saya adalah anak yang cukup berani di zaman saya ...",
  ui_story_30460601_104_dialog_content = "Tidak, bukan Anda profesor. Akulah pahlawannya, dan ini adalah hadiahku karena telah membaca ceritamu yang bertele-tele.",
  ui_story_30460601_105_dialog_content = "Eh? T-Tapi aku mempertaruhkan nyawaku untuk tentakel ini tiga puluh tahun yang lalu!",
  ui_story_30460601_106_dialog_content = "Artinya, Anda memiliki waktu tiga puluh tahun untuk merayakan pencapaian Anda, jadi apa lagi yang Anda inginkan? Kecuali, tentu saja, Anda mengarang semuanya...",
  ui_story_30460601_107_dialog_content = "Saya dapat meyakinkan Anda, cerita saya sepenuhnya benar. Silakan bawa mereka, tapi ingat untuk...",
  ui_story_30460601_108_dialog_content = "Tunggu, kemana kamu pergi? Saya belum selesai berbicara! Astaga, apa yang sedang dilakukan gadis kecil itu?",
  ui_story_30460601_109_dialog_content = "Permisi...",
  ui_story_30460601_110_dialog_content = "Nah, jika itu bukan gadis bangsawan kecil dari Uptown!",
  ui_story_30460601_111_dialog_content = "Sepertinya ada yang salah dengan matamu.",
  ui_story_30460601_112_dialog_content = "Kami hanya tidak terbiasa melihat orang-orang bangsawan di pasar kami, itu saja.",
  ui_story_30460601_113_dialog_content = "Oh, nona, kamu sangat cantik. Lihatlah rambutmu yang berkilau!",
  ui_story_30460601_114_dialog_content = "Jadi apa yang membawamu ke Lumopolis Bawah, nona? Anda tidak tersesat, kan?",
  ui_story_30460601_115_dialog_content = "Jika Anda membiarkan saya berbicara, Anda tidak perlu mengajukan pertanyaan yang tidak perlu seperti itu.",
  ui_story_30460601_116_dialog_content = "Saya membutuhkan sirip Mackerel, dan saya membutuhkannya sekarang. Silakan.",
  ui_story_30460601_117_dialog_content = "Bahkan suaranya cantik, bukan begitu?",
  ui_story_30460601_118_dialog_content = "Aku ingat sekarang! Dia adalah bagian dari Keating Paduan suara!",
  ui_story_30460601_119_dialog_content = "Tidak heran dia memiliki suara yang merdu!",
  ui_story_30460601_120_dialog_content = "Benar-benar? Tapi aku tidak mendengar apa yang dia katakan barusan! Bisakah Anda mengatakannya lagi, nona?",
  ui_story_30460601_121_dialog_content = "Memprovokasi Paduan Suara berarti mendatangkan murka Dewa Cahaya.",
  ui_story_30460601_122_dialog_content = "O-Oh, aku sangat menyesal! Aku tidak bermaksud menyinggungmu!",
  ui_story_30460601_123_dialog_content = "Usia yang begitu muda untuk anggota paduan suara. Itu benar-benar sesuatu untukmu!",
  ui_story_30460601_124_dialog_content = "Dedikasikan diri Anda pada Cahaya, bukan pada pengejaran fana Anda yang sepele.",
  ui_story_30460601_125_dialog_content = "Tentu tentu. Ngomong-ngomong, sirip Makarel ini cukup langka, tapi tidak selangka memiliki bangsawan untuk pelanggan. Saya akan dengan senang hati menjualnya kepada Anda!",
  ui_story_30460601_126_dialog_content = "Ulat Koppia... Berukuran sangat besar namun lembut dalam temperamen, ia hidup jauh di dalam hutan, terutama suka tidur.",
  ui_story_30460601_127_dialog_content = "Sebagai keturunan seorang Ksatria, menjelajahi hutan hanyalah salah satu ujian yang diperlukan dalam perjalananku!",
  ui_story_30460601_128_dialog_content = "Saya mungkin sendirian, tetapi selama saya memiliki pedang, saya tidak perlu takut!",
  ui_story_30460601_129_dialog_content = "Tanahnya lembut, dan ada aroma yang tidak biasa di udara... Ah!",
  ui_story_30460601_130_dialog_content = "Berdeguk, berdeguk, berdeguk——",
  ui_story_30460601_131_dialog_content = "(Dimana...Dimana aku? Nafas yang hangat dan berirama ini, dan perasaan sentuhan yang lengket ini...)",
  ui_story_30460601_132_dialog_content = "(Aku pasti berada di dalam mulut monster raksasa... Cobaan lain yang harus diatasi!)",
  ui_story_30460601_133_dialog_content = "Wah... Akhirnya bebas.",
  ui_story_30460601_134_dialog_content = "Menjijikkan... Lihat saja semua lendir ini. Syukurlah tidak ada yang melihatku seperti ini.",
  ui_story_30460601_135_dialog_content = "Anda baik-baik saja di sana, si kecil? Apa yang kamu lakukan di hutan sendirian?",
  ui_story_30460601_136_dialog_content = "Saya baik-baik saja. Pedangku bisa menembus tenggorokan monster mana pun!",
  ui_story_30460601_137_dialog_content = "Nah, sejauh yang saya tahu, Anda pernah bertemu dengan Ulat Koppia, bukan?",
  ui_story_30460601_138_dialog_content = "Mereka suka menggali ke dalam tanah dan tidur dengan mulut terbuka lebar. Apakah Anda kebetulan jatuh ke mulutnya?",
  ui_story_30460601_139_dialog_content = "Y-Ya, tapi hanya karena tujuan percobaanku adalah untuk mendapatkan sebagian lendirnya! Itu saja!",
  ui_story_30460601_140_dialog_content = "Hei, perhatikan langkahmu! Anda tidak ingin jatuh ke mulut orang lain, bukan?!",
  ui_story_30460601_141_dialog_content = "Ini pasti laboratorium sihir yang terbengkalai itu Carleen memberitahu saya tentang.",
  ui_story_30460601_142_dialog_content = "Ini sangat besar dan jauh dari jalan. Carleen bahkan menugaskan tim tentara untuk menjaga perimeter.",
  ui_story_30460601_143_dialog_content = "Bahkan jika sesuatu benar-benar terjadi, saya yakin mereka dapat menangani semuanya dengan cepat.",
  ui_story_30460601_144_dialog_content = "Kukira Carleen harus benar-benar peduli membiarkan anak-anak itu menjelajah dan belajar.",
  ui_story_30460601_145_dialog_content = "Aku ingin tahu apa yang akan mereka hasilkan?",
  ui_story_30460601_146_dialog_content = "♪Bahan-bahannya sudah terkumpul, waktunya sekarang.♪",
  ui_story_30460601_147_dialog_content = "♪ Saat kuali menggelembung, baca mantranya dengan keras!♪",
  ui_story_30460601_148_dialog_content = "♪Api yang berkedip-kedip dan ramuan yang berputar-putar,♪",
  ui_story_30460601_149_dialog_content = "♪Sihir sejati tidak perlu diperkenalkan!♪",
  ui_story_30460601_150_dialog_content = "♫May hati muda kita menghembuskan kehidupan baru ke dalam mantra ini!♫",
  ui_story_30460601_151_dialog_content = "(Mata mereka bersinar sangat terang. Pasti seperti inilah rupa anak-anak ketika mereka sedang bersenang-senang belajar.)",
  ui_story_30460601_152_dialog_content = "Uhuk uhuk! Begitu banyak asap!",
  ui_story_30460601_153_dialog_content = "Tidak baik! Aku tidak bisa melihat apa-apa!",
  ui_story_30460601_154_dialog_content = "Sebuah bayangan! Muncul dari asap!",
  ui_story_30460601_155_dialog_content = "Saya pikir itu bergerak!",
  ui_story_30460601_156_dialog_content = "Oh tidak, saya merasakan gelombang energi yang sangat kuat! Dapatkan di belakangku, teman-teman!",
  ui_story_30460601_157_dialog_content = "Dan apa sebenarnya yang akan ANDA lakukan?",
  ui_story_30460601_158_dialog_content = "Bukankah seharusnya kamu yang bersembunyi di belakang kami?",
  ui_story_30460601_159_dialog_content = "Kami telah memberi tahu Anda sebelumnya, kami akan melindungi Anda saat diperlukan.",
  ui_story_30460601_160_dialog_content = "Tolong jangan khawatirkan kami.",
  ui_story_30460601_161_dialog_content = "<color=#e8d9bb>Berdebar--</color>",
  ui_story_30460601_162_dialog_content = "Benar-benar suara yang memekakkan telinga! Apakah itu setan mitos atau sesuatu? Tidak, itu adalah Eclipsite!",
  ui_story_30460601_163_dialog_content = "Tolong biarkan kami pergi.",
  ui_story_30460601_164_dialog_content = "Tolong buka matamu.",
  ui_story_30460601_165_dialog_content = "Itu sama sekali bukan monster——",
  ui_story_30460601_166_dialog_content = "Itu hanya profesor kami.",
  ui_story_30460601_167_dialog_content = "Apa yang sedang terjadi di sini?",
  ui_story_30460601_168_dialog_content = "Buku mantra sihir hitam terlarang?! Saya pikir Kara bertingkah aneh hari ini, jadi saya memutuskan untuk mengikutinya, tetapi tidak pernah saya harapkan ...",
  ui_story_30460601_169_dialog_content = "<color=#e8d9bb>Duaar!</color>",
  ui_story_30460601_170_dialog_content = "Selesai!",
  ui_story_30460601_171_dialog_content = "Sebuah keajaiban lahir!",
  ui_story_30460601_172_dialog_content = "Ini terlihat sedikit aneh ...",
  ui_story_30460601_173_dialog_content = "Tapi juga sedikit lucu!",
  ui_story_30460601_174_dialog_content = "Apa itu... Kue raksasa?",
  ui_story_30460601_175_dialog_content = "Tetap kembali! Kue ini masih merupakan karya ilmu hitam! Kemungkinan besar beracun!",
  ui_story_30460601_176_dialog_content = "Mmm, tidak heran kue ini dilarang. Sangat lezat!",
  ui_story_30460601_177_dialog_content = "K-Kamu sudah makan?! Ludahkan sekarang juga, Kara!",
  ui_story_30460601_178_dialog_content = "Mereka mengatakan kelezatan di sebelah kesalehan, Anda tahu?",
  ui_story_30460601_179_dialog_content = "Bukan kamu juga, Pierre?!",
  ui_story_30460601_180_dialog_content = "Wah, ini benar-benar enak! Coba beberapa, profesor!",
  ui_story_30460601_181_dialog_content = "Saya bisa melihat anak-anak melakukan ini, Tn. Caelestite, tapi Anda? Tolong hentikan kebodohan ini...",
  ui_story_30460601_182_dialog_content = "Saya tidak tahu pare dan paprika hijau bisa digunakan untuk membuat sesuatu yang begitu lezat!",
  ui_story_30460601_183_dialog_content = "Melon pahit dan paprika, katamu? Yah, kedengarannya cukup sehat... Ah, sialnya, aku akan mencobanya.",
  ui_story_30460601_184_dialog_content = "Kata saya! Ini benar-benar enak!",
  ui_story_30460601_185_dialog_content = "Dan dengan itu, percobaan kami akhirnya berakhir.",
  ui_story_30460601_186_dialog_content = "Saya rasa tidak, Dian! Masalah ini masih perlu dilaporkan ke Akademi.",
  ui_story_30460601_187_dialog_content = "Kue yang sehat dan lezat ini harus dibagikan ke seluruh sekolah!",
  ui_story_30460601_188_dialog_content = "*Kunyah* Kue ini enak dan semuanya...",
  ui_story_30460601_189_dialog_content = "*Kunyah* Tapi masih ada satu masalah kecil.",
  ui_story_30460601_190_dialog_content = "* Munch * Kami ditipu, bukan?",
  ui_story_30460601_191_dialog_content = "*Kunyah* Ini jelas buku resep, bukan buku ilmu hitam.",
  ui_story_30460601_192_dialog_content = "*Kunyah* Kamu baru menyadarinya sekarang...?",
  ui_story_30460601_193_dialog_content = "Ke... Kenapa kalian semua berbaring di lantai seperti ini? Apakah kamu terluka?",
  ui_story_30460601_194_dialog_content = "Oh, hai Chloe... Tidak, tidak, jangan menangis! Kami baik-baik saja!",
  ui_story_30460601_195_dialog_content = "Kami baru saja makan begitu banyak kue sehingga kami tidak bisa bergerak.",
  ui_story_30460601_196_dialog_content = "Dan sekarang Chloe Crybaby menjadi ketakutan.",
  ui_story_30460601_197_dialog_content = "Di sini, kami menyimpan sepotong kue terakhir.",
  ui_story_30460601_198_dialog_content = "Makan itu. Semoga bisa mengobati rasa sakit hati Anda.",
  ui_story_30460601_199_dialog_content = "Apakah Anda membuat kue ini sendiri?",
  ui_story_30460601_200_dialog_content = "Hah? Kenapa kamu tahu?",
  ui_story_30460601_201_dialog_content = "Yah, kelihatannya agak terlalu aneh untuk dibeli di toko...",
  ui_story_30460601_202_dialog_content = "Saya kira Anda benar. Saya tidak tahu siapa yang akan membeli kue seperti ini ...",
  ui_story_30460601_203_dialog_content = "Sepertinya bayi cengeng itu menjadi lebih perseptif.",
  ui_story_30460601_204_dialog_content = "Tapi tetap saja, penilaiannya hampir tidak objektif.",
  ui_story_30460601_205_dialog_content = "Ya, kue kami memiliki tampilan luar yang tidak sedap dipandang,",
  ui_story_30460601_206_dialog_content = "Tetapi segera Anda akan menemukan bahwa rasanya jauh lebih unggul!",
  ui_story_30460601_207_dialog_content = "Maaf, saya tahu seharusnya saya tidak menilai kue Anda dari penampilannya. Saya akan mencobanya sekarang.",
  ui_story_30460601_208_dialog_content = "Bagaimana?",
  ui_story_30460601_209_dialog_content = "Rasanya enak, tapi kalorinya cukup tinggi. Sangat mudah untuk menambah berat badan jika makan terlalu banyak.",
  ui_story_30460601_210_dialog_content = "Kalori? Bertambah berat badan?",
  ui_story_30460601_211_dialog_content = "Tunggu, apa yang wanita yang memberi kami buku ini katakan lagi?",
  ui_story_30460601_212_dialog_content = "\"Buku ini hanya menakutkan bagi orang dewasa. Untuk anak kecil seperti kita, buku ini sangat aman!\"",
  ui_story_30460601_213_dialog_content = "Jadi bagian yang \"mengerikan\"... Apakah jumlah kalori dalam kue itu?!",
  ui_story_30460601_214_dialog_content = "... Kami telah ditipu ..."
}
return config
